	var wg sync.WaitGroup

	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			msg := formatMessage("developer", id)
			fmt.Println(" ->", msg)
		}(i)
	}

	wg.Wait()
	fmt.Println("Обработка через sync.Pool завершена успешно!")
}

