	"sync"
	"time"
)

func benchMutex(ops int) time.Duration {
	var mu sync.Mutex
	data := make(map[int]int)
	var wg sync.WaitGroup

	start := time.Now()
	const workers = 8
	wg.Add(workers)

	for w := 0; w < workers; w++ {
		go func(workerID int) {
			defer wg.Done()
			for i := 0; i < ops/workers; i++ {
				mu.Lock()
				if i%10 == 0 {
					data[i%100] = i // 10% записей
				} else {
					_ = data[i%100] // 90% чтений
				}
				mu.Unlock()
			}
		}(w)
	}

	wg.Wait()
	return time.Since(start)
}

func benchRWMutex(ops int) time.Duration {
	var mu sync.RWMutex
	data := make(map[int]int)
	var wg sync.WaitGroup

	start := time.Now()
	const workers = 8
	wg.Add(workers)

	for w := 0; w < workers; w++ {
		go func(workerID int) {
			defer wg.Done()
			for i := 0; i < ops/workers; i++ {
				if i%10 == 0 {
					mu.Lock()
					data[i%100] = i // 10% записей
					mu.Unlock()
				} else {
					mu.RLock()
					_ = data[i%100] // 90% чтений
					mu.RUnlock()
				}
			}
		}(w)
	}

	wg.Wait()
	return time.Since(start)
}

func main() {
	const totalOps = 200000

	tMutex := benchMutex(totalOps)
	tRWMutex := benchRWMutex(totalOps)

